public static int sumTo(int n) {
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        sum = sum + i;
    }
    return sum;
}

public static int factorial(int n) {
    int product = 1;
    for (int i = 1; i <= n; i++) {
        product = product * i;
    }
    return product;
}
